import java.util.List;

public final class MoneyTest {
    public static void main(String[] args) {
        checkEvenSplit();
        checkRemainderToFirstParts();
        checkSumInvariant();
        checkInvalidN();
        System.out.println("all tests passed");
    }

    static void checkEvenSplit() {
        List<Money> parts = new Money(100).allocate(4);
        for (Money p : parts) {
            if (p.cents() != 25) {
                throw new AssertionError("even split of 100/4 must be all 25, got " + p.cents());
            }
        }
    }

    static void checkRemainderToFirstParts() {
        List<Money> parts = new Money(100).allocate(3);
        long[] got = {parts.get(0).cents(), parts.get(1).cents(), parts.get(2).cents()};
        long[] expected = {34, 33, 33};
        for (int i = 0; i < 3; i++) {
            if (got[i] != expected[i]) {
                throw new AssertionError("allocate(3) of 100 must be [34,33,33], got part " + i
                        + " = " + got[i]);
            }
        }
    }

    static void checkSumInvariant() {
        for (long total : new long[] {100, 101, 7, 1, 1000003}) {
            for (int n : new int[] {1, 2, 3, 4, 7}) {
                long sum = 0;
                for (Money p : new Money(total).allocate(n)) {
                    sum += p.cents();
                }
                if (sum != total) {
                    throw new AssertionError("allocate(" + n + ") of " + total + " summed to " + sum);
                }
            }
        }
    }

    static void checkInvalidN() {
        try {
            new Money(100).allocate(0);
        } catch (IllegalArgumentException e) {
            return;
        }
        throw new AssertionError("allocate(0) must throw IllegalArgumentException");
    }
}

