import java.util.ArrayList;
import java.util.List;

public final class Money {
    private final long cents;

    public Money(long cents) {
        this.cents = cents;
    }

    public long cents() {
        return cents;
    }

    public Money plus(Money other) {
        return new Money(this.cents + other.cents);
    }

    /** Split this amount into `n` parts as evenly as possible, distributing
     *  the indivisible remainder one cent at a time to the FIRST parts, so
     *  the parts always sum back to the original and differ by at most 1. */
    public List<Money> allocate(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive: " + n);
        }
        long base = cents / n;
        long remainder = cents - base * n; // works for negative cents too
        List<Money> parts = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            long extra = i < remainder ? 1 : 0;
            parts.add(new Money(base + extra));
        }
        return parts;
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Money && ((Money) o).cents == this.cents;
    }

    @Override
    public int hashCode() {
        return Long.hashCode(cents);
    }
}

